const l={"Dominican Republic":[{emoji:"🤙",headline:"Greeting when you walk in is customary in the DR",body:`It's customary to greet when you walk into a room or a shop: a quick "buenas" to everyone is expected, even in a busy colmado. Leaving without saying goodbye can also come across as rude.`,tip:"Start every interaction with a greeting. Skipping it can make you seem cold rather than efficient."},{emoji:"🎵",headline:"Bachata was born in the Dominican Republic",body:"Bachata emerged in the DR in the early 1960s and was looked down on as lower-class music for decades before becoming popular worldwide. UNESCO added Dominican bachata to its Intangible Cultural Heritage list in 2019. Today it is one of the DR's best-known cultural exports.",tip:"Bachata and merengue are easy, friendly conversation topics with Dominicans."},{emoji:"🍲",headline:"Sancocho is a beloved traditional dish",body:"Sancocho is a slow-cooked stew with multiple meats, root vegetables, and herbs. It's made for celebrations, Sundays, and hangovers. Being invited to someone's sancocho is a genuine act of hospitality.",tip:"If someone invites you to share their sancocho, say yes. It's a warm gesture of hospitality."},{emoji:"🏪",headline:"The colmado is a neighborhood hub",body:`The colmado is more than a corner store: it's where neighbors gather, buy on credit ("fiado"), catch up on news and listen to music. The owner often knows the families on the block by name.`,tip:"Take a moment to greet the colmado owner. Rushing straight to business can feel impersonal."},{emoji:"⚾",headline:"Baseball is the DR's favorite sport",body:"The Dominican Republic has produced more Major League Baseball players than any other country outside the United States. Pedro Martínez, David Ortiz and Albert Pujols are household names.",tip:"Knowing a Dominican MLB player or two is an easy way into a conversation."},{emoji:"🗣️",headline:"Dominican Spanish often softens final consonants",body:'Dominican speakers often soften or drop the "s" at the end of syllables, so "¿cómo estás?" can sound like "¿cómo etá?". In some areas "r" can sound like "l" or "i" ("puerta" → "puelta" or "pueita"). These are normal regional features.',tip:"If Dominican speech is hard to follow at first, that's normal; many Spanish speakers from other countries need time to adjust too."},{emoji:"💃",headline:"Merengue is the DR's national music and dance",body:"Merengue is widely considered the national music and dance of the Dominican Republic. UNESCO recognized it as Intangible Cultural Heritage in 2016, and November 26 is National Merengue Day. Its signature instruments are the accordion, güira and tambora.",tip:"Dancing is common at Dominican gatherings, and you may well be invited to join in."},{emoji:"🌴",headline:'"Quisqueya" is what Dominicans call their homeland',body:'Quisqueya is a name for the island of Hispaniola traditionally attributed to the Taíno, often translated as "mother of all lands." Dominicans use it with pride: the national anthem begins "Quisqueyanos valientes."',tip:'Recognizing "Quisqueya" and "quisqueyano" shows real cultural awareness.'}],"Puerto Rico":[{emoji:"☕",headline:"Puerto Rico has a long coffee tradition",body:"Coffee has been grown in Puerto Rico's central mountains, around Yauco, Jayuya and Lares, since the 1700s. In the late 1800s Puerto Rican coffee was a major export to Europe and highly regarded there. A café con leche from a local cafetería is a daily ritual.",tip:"Asking where someone's favorite local coffee comes from is a friendly conversation starter."},{emoji:"🇺🇸",headline:"Puerto Ricans are US citizens",body:"Puerto Rico is a US territory, and Puerto Ricans have been US citizens since 1917. Residents of the island can't vote in presidential elections and are represented in Congress by a single non-voting member. The island's political status (statehood, the current commonwealth, or independence) is a long-running debate.",tip:'"El status" is a sensitive topic with strong views on all sides. Listen first before sharing an opinion.'},{emoji:"🎉",headline:"Las Fiestas Patronales happen in every town",body:"Each of Puerto Rico's municipalities holds an annual festival for its patron saint, with live music, food stalls, rides and dancing, often lasting several days. They're a big part of local identity.",tip:"If a fiesta patronal is happening nearby, it's a great window into local life."},{emoji:"🍽️",headline:"Mofongo is one of Puerto Rico's signature dishes",body:"Mofongo is fried green plantain mashed with garlic and chicharrón (crispy pork), often served as a mound and filled with seafood or meat. You'll find it everywhere from roadside stands to upscale restaurants.",tip:"Asking what someone likes in their mofongo is an easy conversation starter."},{emoji:"⚾",headline:"Baseball and boxing are Puerto Rico's best-known sports",body:"Puerto Rico has produced baseball greats like Roberto Clemente and Carlos Beltrán and boxing champions like Wilfredo Gómez and Miguel Cotto. Clemente is widely honored in Puerto Rico: he died in a 1972 plane crash while delivering aid to earthquake victims in Nicaragua.",tip:"Roberto Clemente's story is widely known on the island and is a good conversation topic."},{emoji:"🎵",headline:"Reggaeton was largely born in Puerto Rico",body:"Reggaeton drew on Jamaican dancehall and Panamanian reggae en español, and took its modern form in Puerto Rico in the 1990s. Puerto Rican artists like Daddy Yankee, Don Omar and Bad Bunny brought it to the world.",tip:"Bad Bunny has been one of the most-streamed artists in the world in recent years, so he's an easy topic with younger Puerto Ricans."},{emoji:"🌿",headline:"Spanglish is a completely natural part of daily speech",body:`Code-switching between Spanish and English mid-sentence is completely normal in Puerto Rico ; it's a normal part of bilingual speech, not a sign of confusion. "Voy al mall" or "está on sale" are unremarkable in daily conversation.`,tip:"Don't be surprised by English words in Spanish sentences — just follow the flow naturally."},{emoji:"🏠",headline:"Extended family is a common part of daily life",body:"In Puerto Rico, family often includes cousins, godparents and compadres, and close neighbors of many years. Large multigenerational Sunday gatherings are common.",tip:"Asking about someone's family — even extended relatives — is a sign of genuine interest, not intrusion."}],Mexico:[{emoji:"🌮",headline:"Mexican cuisine is a UNESCO Intangible Cultural Heritage",body:"In 2010, UNESCO recognized traditional Mexican cuisine as Intangible Cultural Heritage, among the first cuisines to receive that status. Regional cooking varies enormously: Oaxacan moles, Yucatecan cochinita pibil and Veracruz seafood are worlds apart.",tip:"Asking where someone is from in Mexico is a good way into a conversation about regional food."},{emoji:"👨‍👩‍👧‍👦",headline:"Sunday family meals are a common Mexican tradition",body:"Long Sunday family meals are a common tradition in Mexico, and grandparents, aunts, uncles and cousins are often involved in day-to-day family life.",tip:"Asking about someone's family is a common, friendly topic."},{emoji:"🎭",headline:"Día de Muertos is a celebration, not a mourning",body:"Día de Muertos (November 1–2) is a joyful reunion with loved ones who have died. Families build altars (ofrendas) with photos, food and marigolds and visit cemeteries. It blends pre-Hispanic traditions honoring the dead with the Catholic All Saints' and All Souls' days, and UNESCO recognized it in 2008.",tip:"Think of it as a celebration of the lives of loved ones, not a mournful occasion."},{emoji:"🤠",headline:"Mexico has strong regional identities",body:"Many Mexicans identify strongly with their city or state: tapatíos (Guadalajara), regiomontanos (Monterrey) and chilangos (Mexico City) each have their own slang, food and friendly rivalries.",tip:"Learning someone's regional origin is key to understanding their slang, humor, and food references."},{emoji:"🎵",headline:"Mariachi is the sound of Mexican celebration",body:"Mariachi bands play at birthdays, serenatas, quinceañeras and even funerals. The tradition comes from western Mexico, especially Jalisco, and UNESCO recognized it as Intangible Cultural Heritage in 2011.",tip:"Knowing a classic mariachi song or two is a lovely way to connect, especially with older Mexicans."},{emoji:"☕",headline:"Café de olla is a traditional Mexican coffee",body:"Café de olla is traditionally brewed in a clay pot (olla de barro) with cinnamon and piloncillo, unrefined cane sugar. It's warm, spiced and very different from espresso culture.",tip:"Café de olla is often served at traditional restaurants and fondas, especially at breakfast."},{emoji:"🏛️",headline:"Mexico has the most UNESCO World Heritage Sites in the Americas",body:"Mexico has more than 30 UNESCO World Heritage Sites, the most in the Americas, including Chichén Itzá, Teotihuacan, Oaxaca's historic center, and the colonial cities of Guanajuato and Puebla.",tip:"Showing interest in pre-Hispanic history beyond the Aztecs (the Maya, Zapotec and others) is much appreciated."},{emoji:"💀",headline:"Calaveritas: funny poems for Día de Muertos",body:"Around Día de Muertos, people in Mexico write calaveritas literarias: short, humorous rhyming verses that imagine friends, family or politicians meeting Death. It's a long tradition of joking about death. Mexico is also known for albures, playful wordplay with double meanings.",tip:"Albures are clever but often risqué, so it's safer to laugh along than to try them as a beginner."}],French:[{emoji:"🥖",headline:"Fresh bread every day is a French habit",body:'Many French people buy fresh bread daily. A 1993 decree defines the "pain de tradition française" (flour, water, salt and yeast or leaven, no additives), and since 1998 only bakers who make their bread on site can call themselves a "boulangerie." UNESCO recognized the baguette in 2022.',tip:"Many French households buy fresh bread every day, often from the same neighborhood boulangerie."},{emoji:"🤝",headline:"Bonjour is non-negotiable",body:'Starting any interaction (entering a shop, asking a question, getting into an elevator) without saying "Bonjour" first is considered rude in France. It opens every door.',tip:'Say "Bonjour" before anything else, every time. It costs nothing and changes everything.'},{emoji:"🍽️",headline:"French meals follow a set structure",body:"A traditional French meal has an entrée (starter), a plat (main course) and dessert, often with a cheese course before dessert. Meals are social and unhurried.",tip:`In France the waiter usually won't bring the bill until you ask for it ("L'addition, s'il vous plaît"). Lingering is normal.`},{emoji:"💬",headline:"Lively debate is a French tradition",body:"Spirited discussion of politics, ideas and food around the dinner table or in a café is a well-known part of French social life. Disagreeing openly is often seen as engagement, not rudeness.",tip:"Having a clear opinion and defending it respectfully usually earns more respect than vague agreement."},{emoji:"🧀",headline:"France has hundreds of cheeses",body:"Charles de Gaulle famously asked how anyone could govern a country with 246 kinds of cheese. Estimates today range from several hundred to more than a thousand varieties. In a traditional meal, cheese is its own course, served before dessert.",tip:"Asking someone their favorite cheese and why is a conversation that can last the entire meal."},{emoji:"👗",headline:'"Haute couture" is a protected term in France',body:`Only fashion houses that meet strict criteria, set by France's fashion federation and approved by the government, may call themselves "haute couture." Paris hosts haute couture weeks twice a year.`,tip:"Paris Fashion Week and the big couture houses are a natural topic in Paris."},{emoji:"🎭",headline:"May 68 still shapes French political culture",body:'The student and worker protests of May 1968 led to major changes, including a large rise in the minimum wage under the Grenelle agreements and university reforms. The French still refer to "Mai 68" as a touchstone for protest.',tip:"France has a long tradition of protest and strikes, and they come up often in conversation."},{emoji:"🏖️",headline:"August is when France shuts down",body:"French workers are legally entitled to five weeks of paid vacation, and many take a long break in August. Paris gets noticeably quieter, and some independent shops and restaurants close for a few weeks.",tip:"Expect slower replies to business emails in August. It's peak vacation season."}],Parisian:[{emoji:"🥖",headline:"Paris crowns its best baguette every year",body:"Paris holds an annual competition for the best baguette in the city. The winning baker supplies bread to the Élysée Palace, the President's residence, for a year. The traditional baguette contains just flour, water, salt and yeast.",tip:"Complimenting the bread at a French meal is always appropriate and appreciated — it shows you understand what matters."},{emoji:"💋",headline:"La bise varies by region",body:"The number of cheek kisses in a greeting varies across France. In Paris it's usually two, in parts of the south often three, and in some places one or four.",tip:"When in doubt, follow the other person's lead."},{emoji:"🍷",headline:"French wine is named after places",body:"Wine traditionally accompanies meals in France. Most French wines are labeled by region or appellation (Bordeaux, Bourgogne, Sancerre) rather than by grape, because the appellation system ties wine to where it's made.",tip:'Ordering by region ("un verre de Bordeaux") sounds natural in France.'},{emoji:"🗣️",headline:"In Paris, trying some French matters more than perfection",body:'The reputation for Parisian rudeness about language is partly myth. What usually matters is trying: starting with "Bonjour, parlez-vous anglais ?" goes much further than launching straight into English.',tip:'Always greet with "Bonjour" before anything else.'},{emoji:"🎨",headline:"Paris was the center of modern art for a century",body:"From Impressionism through Cubism and Surrealism, Paris drew artists and writers from around the world: Picasso, Modigliani, Hemingway, James Baldwin and many more lived and worked here. The Louvre, Musée d'Orsay and Centre Pompidou hold some of the world's most famous art.",tip:'Showing genuine interest in a specific painting or artist at a Paris museum earns more respect than general enthusiasm for "art."'},{emoji:"🧀",headline:"France has hundreds of cheeses",body:"De Gaulle famously asked how you can govern a country with 246 kinds of cheese. Estimates today range from several hundred to more than a thousand. Each region has its own cheeses, and a cheese course at dinner is a tradition.",tip:"Asking which regional cheese someone recommends is an excellent French conversation starter — opinions will be strong and detailed."},{emoji:"📚",headline:"Debate is part of Paris café culture",body:"Paris cafés have a long tradition as places for discussion and debate. Disagreeing openly is often seen as engagement rather than rudeness.",tip:"Don't be afraid to respectfully push back in a discussion. It's usually welcomed."},{emoji:"☕",headline:"Paris café terraces are an institution",body:"Sitting on a café terrace for an hour over a single coffee is completely normal in Paris. Cafés like Les Deux Magots and Café de Flore became famous as meeting places for writers and philosophers such as Sartre and Simone de Beauvoir.",tip:"Nobody will rush you at a Paris café. Lingering is part of the experience."}],"Southern French":[{emoji:"🌿",headline:"Weekly markets are a Provençal tradition",body:"Towns across Provence, like Aix-en-Provence, Arles and Apt, hold open-air markets on set days of the week. Locals shop for produce, olives, cheese and lavender and catch up with neighbors.",tip:"Shopping at a Provençal market and asking vendors about their products earns warm, extended conversations."},{emoji:"🎯",headline:"Pétanque was born near Marseille",body:"Pétanque, the game of tossing metal balls toward a small wooden jack, was invented in La Ciotat, near Marseille, in 1907. It's played in village squares across the south, often in the shade of plane trees.",tip:"Watching (or joining) a game of pétanque is a classic way to start a conversation in the south."},{emoji:"🥗",headline:"Bouillabaisse is Marseille's culinary identity",body:"Bouillabaisse, the saffron-scented fish stew of Marseille, has a 1980 charter drawn up by local restaurants that lists the fish it should include and how it's served: the broth first, then the fish.",tip:"Asking a Marseillais where to find the best bouillabaisse is guaranteed to produce an enthusiastic, opinionated response."},{emoji:"🎭",headline:"Occitan shaped the speech of the south",body:'Occitan, the medieval language of the troubadours, was widely spoken across southern France for centuries. French largely replaced it, but Occitan words, place names and expressions remain. In parts of the south, "adieu" (from Occitan "adiu") is still used casually for hello or goodbye.',tip:`If someone in the south greets you with "adieu," it's friendly, not a final farewell.`},{emoji:"🏖️",headline:"The Côte d'Azur changed how the world vacations",body:"In the 19th century, the French Riviera was mainly a winter resort for wealthy British and Russian visitors. Nice's Promenade des Anglais is named after the English community that funded it. Summer seaside holidays there only took off in the 20th century.",tip:"Locals often enjoy talking about the region's history beyond its celebrity image."},{emoji:"🫒",headline:"Olive oil has deep roots in the south",body:"Olives were brought to southern France by Greek settlers around 2,600 years ago. Several regions have protected olive oils, and Nyons in Provence received France's first olive oil appellation (AOC) in 1994.",tip:"Asking about local olive oil varieties at a southern French table is always welcome."},{emoji:"🎵",headline:"Marseille is a major hub of French rap",body:"Marseille, founded by Greek settlers around 600 BC and often called France's oldest city, is also its biggest port. That mix of cultures shows in its music: Marseille is home to IAM and Jul, two of French rap's biggest names.",tip:"Marseille's music scene is a source of local pride."},{emoji:"⚽",headline:"Olympique de Marseille is a passion in the south",body:`Olympique de Marseille (OM) vs. Paris Saint-Germain, "Le Classique," is France's biggest football rivalry. In 1993, OM became the first French club to win the European Champions League.`,tip:"In Marseille, be careful praising PSG until you know who you're talking to."},{emoji:"🌅",headline:"Provence's light drew famous painters",body:"Paul Cézanne painted Mont Sainte-Victoire near Aix-en-Provence dozens of times, and Vincent van Gogh moved to Arles in 1888 in search of the southern light.",tip:"Mentioning Cézanne's connection to Aix-en-Provence is a nice touch with locals."}],Italian:[{emoji:"🍕",headline:"Italian pizza differs from international pizza",body:"A Neapolitan pizza has a soft, charred crust and few toppings. In Rome, pizza al taglio is sold by weight in rectangular slices. Thick or stuffed crusts and piles of toppings are not traditional in Italy.",tip:'"Pepperoni" is not an Italian word — peperoni (one p) means bell peppers. If you want spicy sausage, ask for salame piccante.'},{emoji:"☕",headline:"Cappuccino is a morning drink in Italy",body:'Italians traditionally drink cappuccino only in the morning; many believe milky coffee after a meal is bad for digestion. After lunch or dinner, the usual order is an espresso, simply "un caffè."',tip:`After a meal, just say "un caffè" — you'll get a perfect espresso and look like you know what you're doing.`},{emoji:"👨‍👩‍👧‍👦",headline:"Family ties are traditionally strong in Italy",body:"Family ties in Italy are strong and multigenerational. Italians leave their parents' home at around 30 on average, one of the highest ages in the EU. Sunday lunch with the extended family is a tradition in many households.",tip:"Asking about someone's family is a common, friendly way to start a conversation in Italy."},{emoji:"🤌",headline:"Italian hand gestures have specific meanings",body:`The famous pinched-fingers gesture (ma che vuoi?) means "what do you want?" or "what are you talking about?" Other common gestures mean "perfect," "I don't care," or "let's eat." Gestures are a real part of how Italians communicate.`,tip:"Watching Italian gestures and asking what they mean is a conversation that will make any Italian laugh and teach you immediately."},{emoji:"⚽",headline:"Calcio is a national passion",body:"Italian football (Serie A) has some of the world's most passionate fans. Big rivalries include Juventus, Inter and AC Milan in the north, Roma in the center and Napoli in the south. Roberto Baggio, Paolo Maldini and Francesco Totti are legends.",tip:"Asking which club team someone supports is always safe — just don't express a conflicting allegiance immediately."},{emoji:"🎨",headline:"Italy has the most UNESCO World Heritage Sites in the world",body:"Italy has about 60 UNESCO World Heritage Sites, more than any other country, from the historic centers of Rome and Florence to Venice, Pompeii, the Amalfi Coast and the Cinque Terre.",tip:"Asking an Italian about what's special about their specific region always unlocks pride-filled conversation."},{emoji:"🧾",headline:"Italian shops must give you a receipt",body:`Businesses in Italy are legally required to give customers a receipt (scontrino). Customers used to be fined for leaving without one, but that rule was dropped years ago. Since 2021 there's even a "receipt lottery" that rewards paying by card.`,tip:'"Lo scontrino, per favore" is a useful phrase if you need your receipt.'},{emoji:"⏰",headline:'The "academic quarter hour"',body:`Italian universities have a tradition called the "quarto d'ora accademico": a lecture announced for 10:00 often starts at 10:15. Social life also runs later than in many countries; dinner usually starts around 8 or 9 pm, later in the south.`,tip:"For a dinner at someone's home, arriving a few minutes after the stated time is normal."},{emoji:"🏙️",headline:"Local identity is strong in Italy",body:`Italy only became one country in 1861, and regional and local identity remains strong. Italians even have a word for attachment to one's own town: "campanilismo," from campanile, the town's bell tower. Dialects, food and customs change from region to region.`,tip:"Ask where in Italy someone is from. Their region shapes their food, dialect and traditions."},{emoji:"👗",headline:'"La bella figura" is a well-known Italian social ideal',body:'"La bella figura," literally "the beautiful figure," is the Italian ideal of presenting yourself well: dressing appropriately, behaving with composure and making a good impression. "Fare una brutta figura" means to make a bad impression.',tip:"Dressing neatly in Italy is often seen as a form of respect for the people around you."},{emoji:"☕",headline:"Espresso at the bar is a daily ritual",body:"Many Italians drink espresso standing at the bar, which is usually cheaper than sitting at a table. It's a quick daily ritual rather than a drink to linger over. Starbucks only opened its first Italian store in 2018.",tip:'To blend in, order "un caffè" and drink it at the counter.'},{emoji:"🎭",headline:"Opera is living culture in Italy",body:"La Scala in Milan, the Arena di Verona and Teatro di San Carlo in Naples are working theaters with devoted audiences. Booing a weak performance at La Scala is a famous tradition, and UNESCO recognized the practice of Italian opera singing in 2023.",tip:"Expressing genuine interest in opera — even just asking which composer someone prefers — opens a passionate conversation with culturally-minded Italians."}],Neapolitan:[{emoji:"🍕",headline:"Modern pizza was born in Naples",body:`The art of the Neapolitan pizzaiolo is on UNESCO's Intangible Cultural Heritage list (2017), and "pizza napoletana" is protected by EU rules. Traditional pizza is baked in a wood-fired oven at around 430–480 °C for 60–90 seconds.`,tip:'In Naples you can eat pizza with a knife and fork at the table, or folded "a portafoglio" (like a wallet) on the street.'},{emoji:"🎭",headline:"Pulcinella is Naples' ancient alter ego",body:"Pulcinella, the masked character of the commedia dell'arte, has represented Naples since the 17th century: clever, irreverent and always surviving by his wits. Neapolitans see their own humor in him.",tip:"Pulcinella masks and figurines are sold all over Naples, and he still appears in puppet shows and the presepe."},{emoji:"☕",headline:'Naples gave the world "caffè sospeso"',body:`Coffee is a serious ritual in Naples. The city is credited with the tradition of the caffè sospeso ("suspended coffee"): paying for an extra coffee so someone who can't afford one can have it later.`,tip:"Ordering a caffè sospeso is one of the most Neapolitan gestures there is."},{emoji:"🎵",headline:"Neapolitan song shaped Italian music history",body:`"'O sole mio" and "Funiculì, funiculà" are Neapolitan songs, written in Neapolitan. Naples' Teatro di San Carlo, opened in 1737, is the oldest continuously active opera house in Europe.`,tip:`Knowing that "'O sole mio" is in Neapolitan, not standard Italian, is appreciated by locals.`},{emoji:"🌋",headline:"Naples lives beside Vesuvius",body:"Mount Vesuvius buried Pompeii and Herculaneum in 79 AD and last erupted in 1944. Around three million people live in the wider area around it, making it one of the most densely populated volcanic regions in the world.",tip:`"Vivere alla giornata" (living day by day) is an expression you'll hear in Naples.`},{emoji:"🤌",headline:"Neapolitan dialect is not just an accent",body:`Neapolitan (napulitano) is a Romance language with its own grammar, vocabulary and literary tradition. Words like "guagliò" (hey, kid / buddy) and "jamme" (let's go) are Neapolitan, not Italian.`,tip:"Neapolitan is a language with its own literature and song tradition; recognizing a few words is a nice touch."},{emoji:"🏛️",headline:"Naples contains 2,800 years of layered history",body:"Founded by Greek colonists, Naples was later ruled by Romans, Normans, Aragonese, Spanish, Bourbons and Napoleon's French. Its historic center is a UNESCO World Heritage Site, and Napoli Sotterranea, the underground city, contains ancient Greek and Roman cisterns and WWII air-raid shelters.",tip:"Showing genuine curiosity about Naples's layered history rather than just pizza and the waterfront marks you as a serious visitor."},{emoji:"🎄",headline:"Naples has a street of nativity-scene makers",body:"Via San Gregorio Armeno in Naples is lined with workshops making handcrafted figurines for presepi (nativity scenes), a tradition that flourished in the 1700s. Alongside the holy family, artisans make figures of footballers, celebrities and politicians.",tip:"Visiting San Gregorio Armeno around Christmas is a quintessential Neapolitan experience."}],Portuguese:[{emoji:"🎵",headline:"Fado is a Portuguese song tradition on UNESCO's heritage list",body:'Fado (from the Latin "fatum," fate) is an emotional song tradition that emerged in Lisbon in the early 19th century. It is built around saudade, a longing for something lost. UNESCO recognized fado in 2011, and Amália Rodrigues is often called the "Queen of Fado".',tip:"Traditional fado houses expect silence during a song. Talking is frowned upon."},{emoji:"💭",headline:'"Saudade" is untranslatable but essential',body:"Saudade has no direct English equivalent: it describes a deep longing for someone or something absent, often mixed with fondness for the memory. It's a central theme in Portuguese music and literature.",tip:"When a Portuguese person mentions saudade, take it seriously — they're sharing something emotionally significant."},{emoji:"🐟",headline:'Bacalhau has "365 recipes"',body:"A popular Portuguese saying claims there's a bacalhau (salt cod) recipe for every day of the year. Salt cod kept well on long sea voyages and became a staple, and it's often called Portugal's national dish.",tip:"Asking which bacalhau preparation is someone's favorite is a question that will start a long and enthusiastic conversation."},{emoji:"⚽",headline:"Football is Portugal's national passion",body:'The "Big Three" (Benfica, Sporting CP and FC Porto) divide Portuguese loyalties. Cristiano Ronaldo is a national hero, and Portugal won the European Championship in 2016.',tip:'Ask which of the "Big Three" someone supports before mentioning any team — the rivalry is intense.'},{emoji:"🌍",headline:"Portugal's empire lasted nearly 600 years",body:"From the conquest of Ceuta in 1415 until Macau's handover to China in 1999, Portugal held overseas territories, which makes its empire one of the longest-lasting in history. Today Portuguese is spoken by more than 250 million people.",tip:"The colonial past is a sensitive subject. Approach it with care rather than as small talk."},{emoji:"🚋",headline:"Lisbon's tram 28 is an institution",body:"Tram 28 winds through some of Lisbon's oldest and hilliest neighborhoods: Graça, Alfama, Baixa and Estrela. The yellow trams (elétricos) are a symbol of the city.",tip:"Ride early in the morning to avoid the crowds."},{emoji:"🏄",headline:"Nazaré holds the record for the biggest wave ever surfed",body:"Nazaré holds the Guinness World Record for the largest wave ever surfed: 26.21 meters (86 ft), ridden by Sebastian Steudtner in 2020. Ericeira, Peniche and the Algarve are also major surf destinations.",tip:'Surf vocabulary: "onda" (wave), "prancha" (board), "apanhar ondas" (to catch waves, in Portugal).'}],Brazilian:[{emoji:"⚽",headline:"Brazil has won five World Cups",body:'Brazil has won the FIFA World Cup five times (1958, 1962, 1970, 1994 and 2002), more than any other nation. Pelé is widely regarded as one of the greatest footballers of all time. The 1950 defeat by Uruguay at the Maracanã, the "Maracanazo," is still widely remembered in Brazil.',tip:'"Para qual time você torce?" (which team do you support?) is a common conversation starter.'},{emoji:"🎉",headline:"Carnival is Brazil's biggest party",body:"Carnival takes place in the days before Lent. Rio's Carnival is recognized by Guinness as the largest in the world, with competitive samba-school parades. Salvador's Carnival is a huge street party, and every region celebrates in its own way.",tip:"Knowing that Carnival varies by city (Rio, Salvador, Recife and Olinda) shows cultural depth."},{emoji:"🌳",headline:"About 60% of the Amazon is in Brazil",body:"Roughly 60% of the Amazon rainforest lies within Brazil. The Amazon is home to around 10% of the world's known species, and the Amazon River carries about a fifth of all the fresh water that rivers deliver to the oceans.",tip:"Deforestation and indigenous rights are politically charged topics — listen carefully before weighing in."},{emoji:"🍖",headline:"Churrasco is a social ritual, not just a meal",body:"Brazilian barbecue (churrasco) is often a long social event built around slowly grilled meats. The churrasqueiro (grill master) is a respected role, and weekend churrasco with family and friends is a tradition.",tip:"Arriving at a churrasco too early means you're helping set up — arriving on time means you're ready to eat."},{emoji:"🎵",headline:"Bossa nova was born in Rio de Janeiro",body:'Bossa nova emerged in Rio in the late 1950s through João Gilberto, Tom Jobim and Vinicius de Moraes, and it went on to influence jazz worldwide. "The Girl from Ipanema" is one of the most recorded songs in history.',tip:"Knowing bossa nova and samba as distinct traditions — not the same thing — shows genuine musical awareness."},{emoji:"🌊",headline:"The beach is a social institution in Rio",body:`Rio's beaches are major social spaces. Ipanema and Copacabana are divided by numbered lifeguard stations ("postos"), and each stretch has its own crowd and atmosphere: meeting "no Posto 9" is a classic Rio plan.`,tip:'Locals often name the posto as a meeting point: "Te encontro no Posto 9."'},{emoji:"🤝",headline:"Jeitinho brasileiro — the Brazilian way of finding a way",body:'"Jeitinho brasileiro" is a common Brazilian expression for finding a creative way around a problem or rule. It is discussed both as ingenuity and, critically, as rule-bending.',tip:`"A gente dá um jeito" means "we'll find a way". You'll hear it often.`},{emoji:"🇧🇷",headline:"Brazil is not a Spanish-speaking country",body:"Brazil's language is Portuguese, a legacy of its colonial history. Brazilian Portuguese sounds quite different from European Portuguese, and Brazilians are often surprised when visitors assume they speak Spanish.",tip:"A few words of Portuguese go much further than speaking Spanish to a Brazilian."},{emoji:"💃",headline:"Each region of Brazil has its own music and dance",body:"Samba, forró, axé, baião, pagode, funk carioca and lambada all come from Brazil, and each region has its own styles. Samba de roda from Bahia is recognized by UNESCO.",tip:"Asking where in Brazil someone is from before discussing music and dance will save you from making regional assumptions."},{emoji:"🤗",headline:"Cheek kisses are a common Brazilian greeting",body:"Kisses on the cheek are a common greeting, even with new acquaintances: often one in São Paulo and two in Rio. Touching someone's arm during conversation is also common.",tip:"Follow the other person's lead on greetings."}],"Quebec French":[{emoji:"🗣️",headline:"Quebec French preserved sounds France abandoned",body:'Quebec French kept some features of older French that France dropped, like the pronunciation "moé" and "toé" for moi and toi. It also developed its own, such as the affrication of t and d before "i" and "u" sounds (tu sounds like "tsu", dire like "dzire").',tip:"Don't assume your Parisian-French ear will transfer — give yourself time to adjust to the affrication and vowels."},{emoji:"❄️",headline:"Winter is a core part of the identity",body:"Winter shapes Quebec life, with heavy snow and temperatures that can drop below -30 °C. The Carnaval de Québec, held every winter since 1955 with its snowman mascot Bonhomme Carnaval, is one of the largest winter carnivals in the world.",tip:"Joining in a good-natured complaint about winter is a fast way to bond."},{emoji:"🍟",headline:"Poutine comes from rural Quebec",body:"Poutine (fries, fresh cheese curds and brown gravy) was created in rural Quebec in the late 1950s. Several towns, including Warwick, Drummondville and Victoriaville, claim to be its birthplace. Fresh curds should squeak when you bite them.",tip:`Calling poutine simply "Canadian" can mildly annoy some Quebecers; it's Québécois first.`},{emoji:"🕊️",headline:"The Quiet Revolution remade Quebec in a decade",body:"During the Quiet Revolution of the 1960s, Quebec rapidly modernized: the province created a Ministry of Education (1964), nationalized electricity under Hydro-Québec, and the Catholic Church's role in schools and hospitals shrank dramatically.",tip:"Understanding how recently and deliberately Quebec secularized helps explain its strong feelings about language and identity."},{emoji:"🗳️",headline:"The 1995 referendum still shapes everything",body:'In the 1995 referendum on Quebec sovereignty, "No" won with 50.58% of the vote to 49.42%, a margin of about 54,000 votes. The near-miss still shapes Quebec politics.',tip:"Sovereignty is a sensitive subject. Listen before offering an opinion."},{emoji:"🏒",headline:"Les Canadiens are a cultural institution",body:'The Montreal Canadiens ("le CH") have won 24 Stanley Cups, the most in NHL history. In 1955, the suspension of star Maurice "Rocket" Richard sparked the Richard Riot, often seen as an early moment of French-Canadian assertion.',tip:"Knowing the name Maurice Richard earns real credibility with hockey fans."},{emoji:"🎭",headline:"Montreal punches far above its weight in the arts",body:"Quebec has a thriving francophone arts scene. Cirque du Soleil was founded in Quebec in 1984, and the Montreal International Jazz Festival is recognized by Guinness as the world's largest jazz festival.",tip:"Asking about local festivals is an easy, warm conversation opener in Montreal."},{emoji:"💬",headline:"Joual is reclaimed working-class pride",body:`Joual, the working-class French of Montreal, was long dismissed as "bad French." In 1968, Michel Tremblay's play "Les Belles-sœurs," written in joual, helped reclaim it as an authentic voice of Quebec identity.`,tip:"Avoid judging Quebec French by Parisian standards; the comparison is culturally loaded."},{emoji:"🎵",headline:"Quebec music is confidently distinct from French music",body:"Céline Dion is Quebec's most famous musical export, but the local scene, with artists like Cœur de pirate, Les Cowboys Fringants and Ariane Moffatt, is closely tied to Quebec identity, language and land.",tip:"Asking about Quebec music rather than French music signals that you understand Quebec as culturally distinct — which Québécois deeply appreciate."},{emoji:"🌊",headline:"The St. Lawrence River shaped Quebec civilization",body:"Jacques Cartier sailed up the St. Lawrence in 1535, and Samuel de Champlain founded Quebec City on its banks in 1608. The river was the highway of the fur trade and still defines the province's geography and economy.",tip:'In Quebec the St. Lawrence is "le fleuve," not "la rivière." Using the right word sounds local.'},{emoji:"⚜️",headline:"June 24 is Quebec's Fête nationale",body:"June 24, Saint-Jean-Baptiste Day, has been Quebec's official Fête nationale since 1977. It's celebrated with outdoor concerts, bonfires and fleur-de-lis flags across the province.",tip:'"Bonne Fête nationale!" is the right greeting on June 24.'},{emoji:"🚗",headline:`"Je me souviens" is Quebec's motto`,body:`Quebec's official motto, "Je me souviens" ("I remember"), appears on the province's coat of arms and on every Quebec license plate. Its exact meaning is debated, but it's widely read as a reminder of Quebec's history and identity.`,tip:'You can see "Je me souviens" on every Quebec license plate.'}],Cuba:[{emoji:"🎺",headline:"Cuban music shaped the world's dance floors",body:"Son cubano, which developed in eastern Cuba in the late 1800s, became the foundation that salsa was built on. Mambo and cha-cha-chá were also born in Cuba, and UNESCO recognized Cuban rumba in 2016. Cuba produced legends like Celia Cruz and Compay Segundo.",tip:"Showing appreciation for Cuban music — especially the classic trova and son styles — earns immediate warmth from Cubans."},{emoji:"🚗",headline:"Classic American cars are a living museum",body:`Cuba's streets are known for 1950s American cars kept running for decades through improvised repairs. Many serve as shared taxis called "almendrones."`,tip:"Asking about someone's classic car is a good conversation starter."},{emoji:"🍬",headline:'"Resolver" is the Cuban philosophy of life',body:`"Resolver" (to resolve, to sort out) is the everyday Cuban word for finding a way to get things done despite shortages and red tape. It's one of the most important verbs in Cuban life.`,tip:`Using "resolver" shows you understand Cuban reality — it's one of the most important words in the culture.`},{emoji:"🌆",headline:"Cuban money can be confusing",body:"For decades Cuba used two currencies. The dual system officially ended in 2021, but in everyday life prices may still be quoted in Cuban pesos or in foreign currency, and an informal economy runs alongside the state one.",tip:"If a price is unclear, it's normal to ask which currency it's in."},{emoji:"⚾",headline:"Baseball is Cuba's national obsession",body:"Baseball has been played in Cuba since the 1860s and is the national sport. Cuba's national team won Olympic gold in 1992, 1996 and 2004.",tip:"Baseball is one of the easiest topics to bring up in Cuba."},{emoji:"🤝",headline:"Offering a cafecito is Cuban hospitality",body:"Offering guests a small, strong, sweet coffee (un cafecito) is a common Cuban custom, and being invited into someone's home is a sign of trust.",tip:"Accept the coffee if you can. It's a gesture of welcome."},{emoji:"💬",headline:"Cuban Spanish is fast, musical, and drops syllables",body:'Cuban Spanish has a distinctive rhythm and often drops the final "s." Like other Caribbean Spanish (Puerto Rico and the DR), it often keeps the subject before the verb in questions: "¿Qué tú dices?" instead of "¿Qué dices tú?"',tip:'Recognizing "¿qué tú quieres?"-style questions will help you follow Caribbean Spanish.'},{emoji:"🏥",headline:"Cuba has one of the highest doctor ratios in the world",body:"Cuba has one of the highest numbers of doctors per person in the world, and Cuban medical teams have worked in dozens of countries. Medicine is a source of national pride.",tip:"Healthcare can be a politically charged topic, so follow the other person's lead."}],Colombia:[{emoji:"☕",headline:"Colombia's coffee region is a UNESCO World Heritage Site",body:`Colombia is one of the world's largest coffee producers, famous for its washed Arabica. Its Coffee Cultural Landscape became a UNESCO World Heritage Site in 2011. A "tinto" (a small black coffee) is offered everywhere as a gesture of hospitality.`,tip:"Accepting a tinto when it's offered is a friendly gesture."},{emoji:"💃",headline:"Cali calls itself the world capital of salsa",body:'Cali is known as the "capital mundial de la salsa." Its fast-footed salsa caleña style is famous, the city hosts the World Salsa Festival, and the Feria de Cali every December is a huge celebration.',tip:"Cali has many salsa schools (escuelas de salsa) that offer classes for beginners."},{emoji:"🎪",headline:"Colombia's regions have distinct identities",body:"People from different regions have their own names, accents and slang: paisas from Antioquia (Medellín), costeños from the Caribbean coast, rolos or cachacos from Bogotá, and caleños from Cali.",tip:"Ask where someone is from; it explains a lot about their accent and slang."},{emoji:"🌸",headline:"Medellín's transformation is world-famous",body:"In the early 1990s, Medellín had one of the highest murder rates in the world. Since then, projects like the Metrocable gondolas connecting hillside neighborhoods and library parks have earned international recognition, including being named the world's most innovative city in 2013.",tip:"Acknowledging Medellín's transformation — not just its past — shows you see Colombia as it is, not as it was."},{emoji:"🏆",headline:'"Parce" is classic Colombian slang',body:`"Parcero" or "parce" (friend, buddy) is everyday slang, especially in Medellín. You'll hear it constantly among friends.`,tip:`If a Colombian calls you "parce," it's friendly and casual.`},{emoji:"📚",headline:"García Márquez put Colombian storytelling on the world map",body:'Gabriel García Márquez, born in Aracataca on the Caribbean coast, won the 1982 Nobel Prize in Literature and became the most famous writer of magical realism. "Cien años de soledad" is one of the most widely read novels in Spanish.',tip:'García Márquez and "Cien años de soledad" are an easy way into conversations about books.'},{emoji:"🌺",headline:"Colombia is a major flower exporter",body:"Colombia is the world's second-largest exporter of cut flowers and supplies most of the cut flowers imported into the United States. Medellín's Feria de las Flores each August features the silleteros, growers who carry huge flower arrangements (silletas) on their backs.",tip:"The Desfile de Silleteros (silleteros parade) is the best-known event of the Feria de las Flores."},{emoji:"🎵",headline:"Vallenato is accordion music from Colombia's Caribbean coast",body:"Vallenato, accordion-driven music from Colombia's Caribbean coast, tells stories of love, loss and everyday life. UNESCO recognized it in 2015, and Valledupar hosts its famous Festival de la Leyenda Vallenata. Carlos Vives brought it to global audiences.",tip:"Carlos Vives is a well-known name and an easy way into talking about vallenato."}],Castilian:[{emoji:"🍅",headline:"La Tomatina is a giant tomato fight",body:"On the last Wednesday of August in Buñol, near Valencia, thousands of people throw over a hundred tonnes of ripe tomatoes at each other for one hour. It began in 1945 and today participation is limited by ticket to about 20,000 people.",tip:"Asking about someone's hometown festivals is a good conversation opener in Spain."},{emoji:"🌞",headline:"The siesta tradition",body:"Many shops in Spain, especially in smaller towns, traditionally close for a few hours in the early afternoon, when families gather for lunch. Big-city stores increasingly stay open. Evenings start late: dinner is often at 9 or 10 pm.",tip:"Outside big cities, don't expect small shops to be open in mid-afternoon."},{emoji:"⚽",headline:"El Clásico is one of the world's biggest football rivalries",body:`Real Madrid vs. Barcelona, "El Clásico," is one of the world's biggest sporting rivalries and is often linked to debates about Madrid and Catalan identity.`,tip:"Ask which team someone supports before commenting on football — the answer changes everything about the conversation."},{emoji:"🥘",headline:"Going for tapas is a social tradition",body:'Going for tapas ("ir de tapas") means moving from bar to bar with friends, ordering drinks and small plates. In some cities, like Granada, a free tapa traditionally comes with each drink.',tip:"Ordering one or two tapas per bar and then moving on is a common way to do it."},{emoji:"🎨",headline:"Spain produced Picasso, Dalí, and Goya",body:`Spain gave the world Velázquez, Goya, Picasso and Dalí. Madrid's Prado houses one of the world's great art collections, including Velázquez's "Las Meninas," and Dalí's Theatre-Museum in Figueres is among Spain's most visited museums.`,tip:"Velázquez and Goya at the Prado are a natural topic if you've visited Madrid."},{emoji:"🗣️",headline:`Spain uses "vosotros"; Latin America doesn't`,body:'In most of Spain the informal plural "you" is "vosotros." Latin America uses "ustedes" instead. Most of Spain also pronounces "c" (before e/i) and "z" with a "th" sound.',tip:'Using "vosotros" in Spain sounds natural. In Latin America it marks you as having learned Spanish from Spain.'},{emoji:"🕺",headline:"Flamenco is from Andalusia, not all of Spain",body:"Flamenco grew out of Andalusia, especially its Gitano (Roma) communities, with many cultural influences. UNESCO recognized it in 2010. It's strongly associated with the south, not all of Spain.",tip:"Don't assume every Spaniard dances flamenco; it's rooted in a specific region and community."},{emoji:"🏰",headline:"Muslim rule shaped Spain for nearly 800 years",body:"From 711 to 1492, Al-Andalus, at its height covering most of the Iberian Peninsula, left lasting marks on Spanish architecture (the Alhambra), food and language: thousands of Spanish words come from Arabic. In the 10th century Córdoba was one of Europe's largest cities.",tip:'Words like "aceite", "azúcar" and "ojalá" come from Arabic.'},{emoji:"🥘",headline:"The midday meal is the main meal in Spain",body:"La comida, usually between 2 and 4 pm, is traditionally the main meal of the day. Dinner is lighter and late, rarely before 9 pm, and many restaurant kitchens close between lunch and dinner.",tip:"In the early evening, many people have a snack (la merienda) to bridge the gap before a late dinner."},{emoji:"👋",headline:"Two kisses on the cheek is the usual greeting",body:'In Spain, the usual greeting between women, and between men and women, is two kisses on the cheek ("dos besos"), even on first meetings. Men usually shake hands with each other.',tip:"Let the other person lead the greeting to avoid an awkward bump."},{emoji:"🕐",headline:'Spain runs on "the wrong" time zone',body:"Spain uses Central European Time even though most of it lies geographically in line with the UK and Portugal. Franco switched the clocks in 1940, and it was never changed back, which is why summer sunsets in Madrid come close to 10 pm.",tip:"Meal and shop hours in Spain run later than in most of Europe."}],Sicilian:[{emoji:"🍊",headline:"Sicilian blood oranges owe their color to Etna",body:"The deep red of Sicily's protected blood oranges (Arancia Rossa di Sicilia) develops thanks to the big day-to-night temperature swings around Mount Etna. Sicily is also famous for Bronte pistachios, almonds and lemons.",tip:"Asking about local seasonal produce and where to find it earns rich, detailed responses from Sicilians who take agricultural pride seriously."},{emoji:"🏺",headline:"Sicily was a jewel of the Greek world",body:"Agrigento's Valley of the Temples, a UNESCO site, includes the Temple of Concordia, one of the best-preserved Greek temples in the world. In antiquity, Syracuse was one of the largest and most powerful cities in the Greek world.",tip:"Sicily's Greek, Arab and Norman heritage is visible in sites like Agrigento's Valley of the Temples and Palermo's Arab-Norman churches."},{emoji:"🎭",headline:"Sicilian puppet theater is UNESCO heritage",body:"The Opera dei Pupi, Sicilian puppet theater featuring knights in armor from medieval legends, was recognized by UNESCO in 2001. The traditional marranzano (jaw harp) is another distinctive sound of Sicilian folk culture.",tip:"Asking about traditional Sicilian music rather than Italian pop opens completely different and deeper conversations."},{emoji:"🧁",headline:"Sicilian sweets carry Arab influence",body:'Sicily was under Arab rule from the 9th to the 11th century, which brought sugar cane and citrus and shaped sweets like cassata and cannoli. Marzipan fruit, "frutta di Martorana," is named after a convent in Palermo.',tip:"Granita with brioche for breakfast is a Sicilian summer classic."},{emoji:"🌊",headline:"Sicilians have a complex relationship with the mainland",body:"Sicily joined the unified Kingdom of Italy in 1860–61 and has had special autonomous status since 1946. Many Sicilians feel a strong, distinct identity tied to their own language, history and culture.",tip:"Sicily has its own language, Sicilian, and a distinct food and history; asking about them is a good conversation opener."},{emoji:"🤝",headline:"Hospitality is a Sicilian tradition",body:"Offering food and drink to guests is a strong tradition in Sicily, and hosts often insist more than once.",tip:"Accept what's offered if you can. It's part of being a good guest."},{emoji:"🌋",headline:"Etna is active and central to Sicilian identity",body:"Mount Etna is the tallest active volcano in Europe and a UNESCO World Heritage Site. Its volcanic soil supports vineyards, and Etna DOC, created in 1968, was one of Italy's first protected wine regions.",tip:"Wines from the slopes of Mount Etna, such as Etna Rosso, are a well-known Sicilian specialty."},{emoji:"🗣️",headline:"Sicilian dialect contains Arabic, Greek, and Norman words",body:`Sicilian is a Romance language with words from many rulers: "giarra" (jar) from Arabic, "naca" (cradle) from Greek, and "accattari" (to buy) from Old French. In the 13th century, the poets of Frederick II's court produced the first literary poetry in an Italian vernacular, which Dante praised.`,tip:"Knowing that Sicilian dialect is linguistically distinct from Italian — not just an accent — is a mark of respect that Sicilians genuinely appreciate."}],Haiti:[{emoji:"🌟",headline:"Haiti was born from a successful slave revolution",body:"On January 1, 1804, Haiti became the first independent Black republic and the only nation founded by a successful slave revolt, after defeating Napoleon's forces at the Battle of Vertières in 1803.",tip:"Haiti's revolutionary history is a deep source of pride. Approach it with respect."},{emoji:"🎨",headline:"Haitian painting won world fame in the 1940s",body:"The Centre d'Art in Port-au-Prince, founded in 1944, launched internationally collected Haitian painters like Hector Hyppolite. Their vivid scenes of daily life, history and Vodou are exhibited in museums around the world.",tip:"Showing knowledge of Haitian painting tradition — even just recognizing the style — earns genuine surprise and appreciation from Haitians."},{emoji:"🥁",headline:"Vodou is a religion, not a horror movie",body:`Vodou is a religion with West African roots (Fon, Ewe, Yoruba and Kongo) that blended with Catholicism in Haiti. Haiti officially recognized it as a religion in 2003. Hollywood's "voodoo" bears little resemblance to the real practice.`,tip:"Approach Vodou with curiosity and respect rather than movie stereotypes."},{emoji:"🎵",headline:"Kompa is Haiti's national rhythm",body:`Kompa (konpa) is Haiti's most popular dance music. Nemours Jean-Baptiste created "compas direct" in 1955, drawing on merengue and big-band jazz. It's played at parties, weddings and celebrations.`,tip:"Trying to dance kompa, even badly, is warmly received."},{emoji:"🌺",headline:"Haitian Creole is spoken by virtually all Haitians",body:"Haitian Creole (Kreyòl) is spoken by virtually all Haitians and has been an official language alongside French since 1987. It developed during the colonial era among enslaved Africans and French colonists, and it is a full language with its own grammar.",tip:`Never call Kreyòl "broken French." It's a distinct language.`},{emoji:"🌶️",headline:"Most Haitian dishes start with epis",body:"Griot (fried pork), diri ak djon djon (black mushroom rice), tasso (fried beef) and pikliz (spicy pickled vegetables) are Haitian staples. Most dishes start with epis, a blend of garlic, peppers, herbs and citrus.",tip:"Asking how someone makes their epis is a good conversation starter; recipes vary from family to family."},{emoji:"⛰️",headline:'"Dèyè mòn gen mòn"',body:`One of Haiti's best-known proverbs, "Dèyè mòn gen mòn" ("beyond the mountains, more mountains"), means that after one challenge comes another. It reflects a culture rich in proverbs and in perseverance.`,tip:"Haitian proverbs (pwovèb) come up often in conversation. Learning a few is a great way to connect."},{emoji:"🏔️",headline:'Haiti means "land of high mountains" in Taíno',body:`The Taíno, the island's indigenous people, called it "Ayiti," usually translated as "land of high mountains." When Haiti won independence in 1804, its founders chose this indigenous name.`,tip:'Knowing the etymology of "Haiti" and its connection to Taíno heritage shows the kind of historical depth that Haitians find meaningful.'},{emoji:"🍲",headline:"Joumou soup is eaten on January 1st to celebrate freedom",body:"Soup joumou (pumpkin soup) is eaten every January 1 to celebrate Haitian independence. According to tradition, enslaved people prepared it but weren't allowed to eat it, so sharing it became a symbol of freedom. UNESCO recognized it in 2021.",tip:"Understanding soup joumou as a political and emotional tradition — not just food — shows deep cultural respect."},{emoji:"🤝",headline:"Konbit: neighbors working together",body:"A konbit is the Haitian tradition of collective work, with neighbors gathering to help each other with harvests, building or community projects, often to music. It has roots in West African traditions.",tip:"The konbit spirit of mutual help is a big part of Haitian community life."}]},d={Colombian:"Colombia",Sicily:"Sicilian","European Portuguese":"Portugal",Mexican:"Mexico","Mexican Spanish":"Mexico","Castilian Spanish":"Castilian",Spain:"Castilian","Haitian Creole":"Haiti",Creole:"Haiti",Brazilian:"Brazil","Brazilian Portuguese":"Brazil",Paris:"Parisian",Naples:"Neapolitan",Italian:"Italy","Standard Italian":"Italy",Quebec:"Quebec French",Quebecois:"Quebec French","French Canadian":"Quebec French"};function h(i,n){var a;const o=[i,n,d[i],d[n]];for(const e of o)if(e&&((a=l[e])!=null&&a.length))return{key:e,facts:l[e]};return null}function c(i,n,o=3){const a=h(i,n);if(!a)return[];const{facts:e}=a,t=Math.max(1,Math.floor(e.length/o)),s=[];for(let r=0;r<o&&r*t<e.length;r++)s.push(e[r*t]);return s}function u(i,n){const o=h(i,n);if(!o)return null;const{facts:a}=o,e=new Date().toDateString()+(i||n||"");let t=0;for(const s of e)t=t*31+s.charCodeAt(0)&4294967295;return a[Math.abs(t)%a.length]}export{u as a,c as b,h as g};
